// ============================================================
// Metric descriptions + data-source bindings
//
// Generated by 10 parallel agents from page-rendered metrics in
// app/(dashboard)/metrics/page.tsx. Each description explains:
//   - what:  what the metric measures (plain language for owner)
//   - why:   why it matters / what good vs bad means
//   - how:   formula or method of calculation
//   - current_state: interpretation of current vs target (BIZ + GRI)
//   - sources: where the data comes from
//
// Source types:
//   - survey:   onboarding survey answer (lib/survey-labels.ts)
//   - document: parsed uploaded file (lib/documents/extract.ts)
//   - prisma:   DB model (prisma/schema.prisma)
//   - external: third-party system (GA, KASE, CRM, ERP, social)
//   - manual:   manual owner input
//   - missing:  no source wired yet
// ============================================================

export type MetricSourceType =
  | "survey"
  | "document"
  | "prisma"
  | "external"
  | "manual"
  | "missing";

export interface MetricSource {
  type: MetricSourceType;
  step?: number;
  key?: string;
  label?: string;
  model?: string;
  field?: string;
  doc_type?: string;
  system?: string;
  note?: string;
}

export interface MetricDescription {
  label: string;
  what: string;
  why: string;
  how: string;
  current_state?: string;
  sources: MetricSource[];
}

export interface KpiDescription extends MetricDescription {
  category?: string;
  owner?: string | null;
  method?: string | null;
}

export interface GoalMetricDescription {
  label: string;
  formula: string;
  benchmark: string;
  what: string;
  why: string;
  how: string;
  sources: MetricSource[];
}

export interface GoalFormulaBlock {
  title: string;
  formula: string;
  rules: string[];
  explanation: string;
}

export interface GoalDescriptions {
  number: string;
  title: string;
  formulaBlock?: GoalFormulaBlock;
  items: GoalMetricDescription[];
}

